pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 depositAmount, uint256 extraDeposit) public {
        vm.assume(caller != address(0));
        depositAmount = bound(depositAmount, 1, 1e18);
        extraDeposit = bound(extraDeposit, 0, 1e18);

        vm.deal(caller, depositAmount + extraDeposit);
        vm.prank(caller);
        c.deposit{value: depositAmount}();

        if (extraDeposit > 0) {
            vm.prank(caller);
            c.deposit{value: extraDeposit}();
        }

        bool withdrawReverted = false;
        try c.withdrawAll() {
            // withdrawal succeeded
        } catch {
            withdrawReverted = true;
        }

        assertTrue(!withdrawReverted, "Withdrawal should not revert");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 depositAmount, uint256 depositAmount2) public {
        vm.assume(caller != address(0));
        vm.assume(depositAmount > 0 && depositAmount <= type(uint128).max);
        vm.assume(depositAmount2 > 0 && depositAmount2 <= type(uint128).max);

        // First deposit
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.deposit{value: depositAmount}();

        // Second deposit
        vm.deal(caller, depositAmount2);
        vm.prank(caller);
        c.deposit{value: depositAmount2}();

        // Withdraw all
        vm.prank(caller);
        c.withdrawAll();

        // The bug: balance should be 0 but becomes depositAmount2
        assertTrue(c.balance() == 0);
    }
}

