pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint amount) public {
        vm.assume(caller != address(0));
        vm.assume(amount > 0 && amount <= 1e24);

        vm.deal(caller, amount);
        vm.prank(caller);
        c.deposit{value: amount}();

        vm.prank(caller);
        c.withdrawAll();

        // After a deposit and full withdrawal, caller's credit must be 0
        assertTrue(c.credit(caller) == 0);
    }
}

