pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint amount) public {
        vm.assume(caller != address(0));
        amount = bound(amount, 1, 1e18);
        vm.deal(caller, amount);
        vm.prank(caller);
        c.deposit{value: amount}();
        uint balanceBefore = address(c).balance;
        vm.prank(caller);
        c.withdrawAll();
        assertTrue(address(c).balance == balanceBefore - amount);
    }
}
